var e=[{id:`temperature-fan`,name:`Temperatura → Controlador → Ventilador`,sensor:`temp`,controller:`plc`,actuator:`ventilador`,condition:`Temperatura > 75 °C`,action:`Activa el ventilador de extracción`,detail:`Control térmico de gabinete: el PLC enciende el ventilador cuando la temperatura supera el límite.`,result:`El gabinete pierde calor y la temperatura vuelve al rango seguro.`},{id:`inductive-belt`,name:`Inductivo → Controlador → Motor de banda`,sensor:`inductivo`,controller:`plc`,actuator:`motor-cinta`,condition:`Pieza metálica detectada`,action:`Arranca el motor de la banda transportadora`,detail:`Transporte de piezas: el sensor inductivo confirma el metal y el PLC inicia la banda.`,result:`La pieza avanza a la siguiente estación de proceso.`},{id:`pressure-valve`,name:`Presión → Controlador → Válvula`,sensor:`pres`,controller:`arduino`,actuator:`valvula`,condition:`Presión > 9 bar`,action:`Abre la válvula solenoide de alivio`,detail:`Seguridad de línea: una sobrepresión acciona la válvula para liberar el fluido.`,result:`La presión disminuye hasta regresar al rango de operación.`},{id:`nivel-bomba`,name:`Nivel → PLC → Motobomba`,sensor:`nivel`,controller:`plc`,actuator:`motor`,condition:`Nivel < 60 %`,action:`Arranca la motobomba de llenado`,detail:`Control de nivel en tanque: el PLC mantiene el agua entre consignas arrancando y parando la bomba.`,result:`El tanque recupera su nivel de trabajo.`},{id:`temp-valvula`,name:`Temperatura → Arduino → Válvula`,sensor:`temp`,controller:`arduino`,actuator:`valvula`,condition:`Temperatura > 75 °C`,action:`Abre la válvula de enfriamiento`,detail:`Lazo de climatización: el refrigerante entra cuando el proceso se calienta.`,result:`El refrigerante retira calor del proceso.`},{id:`prox-cilindro`,name:`Proximidad → PLC → Cilindro`,sensor:`prox`,controller:`plc`,actuator:`cilindro`,condition:`Pieza detectada`,action:`Extiende el cilindro de doble efecto`,detail:`Estación de embalaje: el sensor confirma la pieza y el cilindro la empuja a la cinta de salida.`,result:`La pieza es empujada a la cinta de salida.`},{id:`pres-alarma`,name:`Presión → Arduino → Zumbador`,sensor:`pres`,controller:`arduino`,actuator:`zumbador`,condition:`Presión > 9 bar`,action:`Activa la alarma sonora`,detail:`Seguridad de línea neumática: una sobrepresión dispara el zumbador para avisar al operario.`,result:`El operario recibe un aviso de sobrepresión.`},{id:`marcha-piloto`,name:`Proximidad → PLC → Piloto`,sensor:`prox`,controller:`plc`,actuator:`piloto`,condition:`Línea en marcha`,action:`Enciende el piloto verde de estado`,detail:`Señalización de máquina: el piloto comunica el estado del proceso sin pantalla.`,result:`El estado de la máquina se comunica visualmente.`}],t=[{id:`power`,icon:`⚡`,title:`Potencia`,description:`Debe entregar la fuerza, el torque o el caudal que exige la carga.`},{id:`controllability`,icon:`⌘`,title:`Controlabilidad`,description:`La orden debe poder regularse con el controlador disponible.`},{id:`size`,icon:`◇`,title:`Peso y volumen`,description:`El conjunto debe caber en la máquina sin añadir masa innecesaria.`},{id:`precision`,icon:`◎`,title:`Precisión`,description:`La repetibilidad y la exactitud deben corresponder al proceso.`},{id:`speed`,icon:`⏱`,title:`Velocidad`,description:`El actuador debe completar el recorrido o ciclo dentro del tiempo requerido.`},{id:`maintenance`,icon:`⌁`,title:`Mantenimiento`,description:`Se considera desgaste, lubricación, filtros, fugas y facilidad de servicio.`},{id:`cost`,icon:`$`,title:`Costo`,description:`Se compara compra, instalación, consumo y repuestos durante la vida útil.`}],n=[{id:`positioned-conveyor`,situation:`Necesito mover una banda transportadora con posiciones controladas.`,detail:`La carga debe detenerse en puntos repetibles y el controlador trabaja con pulsos digitales.`,options:[{id:`stepper`,label:`Motor paso a paso`},{id:`buzzer`,label:`Zumbador`},{id:`single-cylinder`,label:`Cilindro neumático simple efecto`}],correct:`stepper`,explanation:`El motor paso a paso convierte cada pulso en un ángulo definido y permite posicionar la banda en lazo abierto.`,criteria:[`controllability`,`precision`,`speed`]},{id:`heavy-press`,situation:`Necesito presionar una pieza con mucha fuerza y movimiento lento.`,detail:`La máquina tiene espacio limitado y requiere movimiento suave bajo carga.`,options:[{id:`hydraulic-cylinder`,label:`Cilindro hidráulico`},{id:`pilot`,label:`Piloto luminoso`},{id:`dc-motor`,label:`Motor DC pequeño`}],correct:`hydraulic-cylinder`,explanation:`La presión del aceite multiplicada por el área del pistón produce mucha fuerza con control suave.`,criteria:[`power`,`precision`,`size`]},{id:`liquid-flow`,situation:`Necesito abrir y cerrar el paso de un líquido desde un PLC.`,detail:`La orden es binaria y el fluido debe quedar bloqueado cuando se retira la energía.`,options:[{id:`solenoid-valve`,label:`Válvula solenoide`},{id:`ac-motor`,label:`Motor AC`},{id:`mechanical-lever`,label:`Palanca mecánica`}],correct:`solenoid-valve`,explanation:`La bobina convierte la orden eléctrica en el desplazamiento del émbolo que abre o cierra el paso.`,criteria:[`controllability`,`maintenance`,`cost`]}];export{e as n,t as r,n as t};